import { configured, supabase } from './supabase-client.js';
import * as api from './api.js';

const VERSION='1.0.0-supabase';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const today=()=>new Date().toISOString().slice(0,10);
const dateLabel=d=>d?new Date(`${d}T00:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
let user=null, profile=null, db={lab:null,inventory:[],containers:[],vendors:[],procurement:[],usage:[],audit:[],profiles:[],equipment:[],bookings:[],serviceLogs:[],locations:[],samples:[],acks:[]};
let page='dashboard', search='', selectedInventoryId=null, unsubscribe=null, refreshTimer=null;
const admin=()=>profile?.role==='admin';

function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function fail(e){console.error(e);toast(e?.message||String(e));}
function low(x){return Number(x.current_stock)<=Number(x.min_stock)}
function expiry(date,days=90){if(!date)return null;const a=new Date();a.setHours(0,0,0,0);const d=Math.ceil((new Date(date+'T00:00:00')-a)/86400000);return{days:d,expired:d<0,warning:d>=0&&d<=days}}
function dl(text,name,type='text/plain'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function csv(){const c=['item_code','sku','name','category','cas','current_stock','min_stock','unit','storage','expiry_date','project','unit_cost'];const q=v=>`"${String(v??'').replaceAll('"','""')}"`;return[c.join(','),...db.inventory.map(r=>c.map(k=>q(r[k])).join(','))].join('\n')}
function chip(s){return `<span class="chip ${String(s).toLowerCase()}">${esc(s)}</span>`}
function modal(title,body,onSave,save='Save'){$('#modal').innerHTML=`<div class="modalbg"><div class="modalbox"><div class="modalhead"><b>${esc(title)}</b><button id="mx">✕</button></div><div class="modalbody">${body}</div><div class="modalfoot"><button id="mc">Cancel</button><button class="primary" id="ms">${esc(save)}</button></div></div></div>`;$('#mx').onclick=$('#mc').onclick=()=>$('#modal').innerHTML='';$('#ms').onclick=async()=>{try{await onSave();$('#modal').innerHTML=''}catch(e){fail(e)}}}

async function refresh(){if(!profile)return;db=await api.loadLabData(profile.lab_id);updateNotificationBadges();render()}
function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(fail),250)}
async function establish(session){user=session?.user||null;if(!user){showLogin();return}profile=await api.getProfile(user.id);$('#who').textContent=profile.display_name||user.email;$('#role').textContent=profile.role==='admin'?'Lab Admin':'Lab Member';$('#login').style.display='none';$('#app').hidden=false;await refresh();if(unsubscribe)unsubscribe();unsubscribe=api.subscribeLab(profile.lab_id,scheduleRefresh)}
function showLogin(){user=profile=null;db={lab:null,inventory:[],containers:[],vendors:[],procurement:[],usage:[],audit:[],profiles:[],equipment:[],bookings:[],serviceLogs:[],locations:[],samples:[],acks:[]};$('#app').hidden=true;$('#login').style.display='grid';if(unsubscribe){unsubscribe();unsubscribe=null}}

$('#configWarning').hidden=configured;
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();if(!configured)return;const m=$('#loginMessage');m.textContent='Signing in…';try{const r=await api.signIn($('#email').value.trim(),$('#password').value);m.textContent='';await establish(r.session)}catch(x){m.textContent=x.message}});
if(configured){api.getSession().then(r=>establish(r.session)).catch(fail);supabase.auth.onAuthStateChange((_e,s)=>{if(!s)showLogin()})}

function setPage(next){page=next;search='';$('#search').value='';$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));render()}
$$('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
$('#search').oninput=e=>{search=e.target.value.toLowerCase();render()};
$('#newRequest').onclick=()=>requestModal();
$('#scan').onclick=()=>scanModal();
$('#notificationShortcut').onclick=()=>setPage('notifications');

function metrics(){
  const horizon=db.lab?.expiry_notice_days||90;
  const ex=db.containers.filter(c=>Number(c.quantity_remaining)>0&&c.status==='ACTIVE').map(c=>expiry(c.expiry_date,horizon)).filter(Boolean);
  const month=new Date().toISOString().slice(0,7);
  const monthSpend=db.procurement.filter(r=>String(r.created_at||'').slice(0,7)===month).reduce((s,r)=>s+Number(r.ordered_total||0),0);
  const stockValue=db.inventory.reduce((s,x)=>s+Number(x.current_stock||0)*Number(x.unit_cost||0),0);
  return {
    inventory:db.inventory.length,
    containers:db.containers.filter(c=>c.status==='ACTIVE'&&Number(c.quantity_remaining)>0).length,
    low:db.inventory.filter(low).length,
    pending:db.procurement.filter(r=>!['Delivered','Closed'].includes(r.status)).length,
    requested:db.procurement.filter(r=>r.status==='Requested').length,
    delayed:db.procurement.filter(r=>r.status==='Delayed'||(['Ordered','Partial'].includes(r.status)&&r.expected_date&&r.expected_date<today())).length,
    ordered:db.procurement.reduce((s,r)=>s+Number(r.ordered_total||0),0),
    monthSpend, stockValue,
    expired:ex.filter(e=>e.expired).length,
    expiring:ex.filter(e=>e.warning).length
  };
}
function stats(){const d=metrics();return `<div class="stats"><div class="stat"><span>Inventory</span><strong>${d.inventory}</strong><small>${d.containers} active containers</small></div><div class="stat"><span>Low stock</span><strong>${d.low}</strong><small>at/below minimum</small></div><div class="stat"><span>Expiry alerts</span><strong>${d.expiring+d.expired}</strong><small>${d.expired} expired</small></div><div class="stat"><span>Monthly spend</span><strong>${money(d.monthSpend)}</strong><small>${d.pending} open requests</small></div></div>`}

function buildNotifications(){
  const list=[]; const horizon=db.lab?.expiry_notice_days||90;
  db.inventory.forEach(x=>{if(low(x))list.push({key:`low:${x.id}`,type:'low-stock',severity:Number(x.current_stock)===0?'critical':'warning',title:`Low stock: ${x.name}`,body:`${x.current_stock} ${x.unit} remaining · minimum ${x.min_stock}`,entity:'inventory',entityId:x.id,sort:30})});
  db.containers.forEach(c=>{if(c.status!=='ACTIVE'||Number(c.quantity_remaining)<=0)return;const e=expiry(c.expiry_date,horizon);const inv=db.inventory.find(x=>x.id===c.inventory_id);if(e?.expired)list.push({key:`expired:${c.id}:${c.expiry_date}`,type:'expiry',severity:'critical',title:`Expired container: ${inv?.name||c.container_code}`,body:`${c.container_code} expired ${Math.abs(e.days)} day${Math.abs(e.days)===1?'':'s'} ago`,entity:'inventory',entityId:c.inventory_id,sort:50});else if(e?.warning)list.push({key:`expiry:${c.id}:${c.expiry_date}`,type:'expiry',severity:e.days<=14?'critical':'warning',title:`Expiring soon: ${inv?.name||c.container_code}`,body:`${c.container_code} expires in ${e.days} day${e.days===1?'':'s'} (${dateLabel(c.expiry_date)})`,entity:'inventory',entityId:c.inventory_id,sort:40-e.days/1000})});
  db.procurement.forEach(r=>{const overdue=['Ordered','Partial'].includes(r.status)&&r.expected_date&&r.expected_date<today();if(r.status==='Delayed'||overdue)list.push({key:`delay:${r.id}:${r.expected_date||''}`,type:'procurement',severity:'critical',title:`Delayed procurement #${r.id}`,body:`${r.project||'General'} · expected ${dateLabel(r.expected_date)}`,entity:'procurement',entityId:r.id,sort:45});if(admin()&&r.status==='Requested')list.push({key:`request:${r.id}`,type:'procurement',severity:'info',title:`Purchase request awaiting action`,body:`Request #${r.id} · ${r.project||'General'}`,entity:'procurement',entityId:r.id,sort:20});if(admin()&&r.status==='Delivered'&&!r.invoice_ref)list.push({key:`invoice:${r.id}`,type:'procurement',severity:'info',title:`Invoice pending for delivered order`,body:`${r.po_number||`Request #${r.id}`} · ${money(r.ordered_total)}`,entity:'procurement',entityId:r.id,sort:15})});
  db.equipment.forEach(e=>{for(const [kind,due,label] of [['calibration',e.calibration_due,'Calibration'],['maintenance',e.maintenance_due,'Maintenance']]){const x=expiry(due,30);if(x?.expired||x?.warning)list.push({key:`equipment:${kind}:${e.id}:${due}`,type:'equipment',severity:x.expired||x.days<=7?'critical':'warning',title:`${label} due: ${e.name}`,body:x.expired?`${Math.abs(x.days)} day(s) overdue`:`Due in ${x.days} day(s)`,entity:'equipment',entityId:e.id,sort:x.expired?48:32})}});
  db.samples.forEach(s=>{if(s.status!=='ACTIVE')return;const x=expiry(s.expiry_date,30);if(x?.expired||x?.warning)list.push({key:`sample:${s.id}:${s.expiry_date}`,type:'sample',severity:x.expired?'critical':'warning',title:`Sample expiry: ${s.name}`,body:`${s.sample_code} · ${x.expired?'expired':'expires'} ${dateLabel(s.expiry_date)}`,entity:'sample',entityId:s.id,sort:x.expired?46:28})});
  const ack=new Set((db.acks||[]).map(a=>a.notification_key));
  return list.map(n=>({...n,acknowledged:ack.has(n.key)})).sort((a,b)=>Number(a.acknowledged)-Number(b.acknowledged)||b.sort-a.sort||a.title.localeCompare(b.title));
}
function unreadNotifications(){return buildNotifications().filter(n=>!n.acknowledged)}
function updateNotificationBadges(){const n=unreadNotifications().length;for(const id of ['#notificationCount','#notificationShortcutCount']){const el=$(id);if(!el)continue;el.textContent=n>99?'99+':String(n);el.hidden=n===0}}
function alertStrip(){const n=unreadNotifications();if(!n.length)return'';return `<div class="alerts notification-strip"><div><b>⚠ ${n.length} item${n.length===1?'':'s'} need attention</b><div class="sub">${n.slice(0,3).map(x=>esc(x.title)).join(' · ')}</div></div><button id="openAlerts">Review</button></div>`}

function render(){
  if(!profile)return;
  if(page==='dashboard')dashboardPage();
  else if(page==='inventory')inventory();
  else if(page==='inventory-detail')inventoryDetail();
  else if(page==='procurement')procurement();
  else if(page==='vendors')vendors();
  else if(page==='equipment')equipmentPage();
  else if(page==='samples')samplesPage();
  else if(page==='notifications')notificationCenter();
  else if(page==='analytics')analytics();
  else if(page==='team')teamPage();
  else settings();
}

function dashboardPage(){
  const d=metrics(), notes=unreadNotifications().slice(0,5), statusCounts={};db.procurement.forEach(r=>statusCounts[r.status]=(statusCounts[r.status]||0)+1);
  const maxStatus=Math.max(1,...Object.values(statusCounts));
  $('#page').innerHTML=`<div class="page-head"><div><h1>Dashboard</h1><p>${esc(db.lab?.name||'Laboratory')} · operational overview</p></div><div class="actions">${admin()?'<button id="dashAddItem">+ Inventory</button>':''}<button class="primary" id="dashRequest">+ Request</button></div></div>
  <div class="dashboard-metrics">
    <div class="metric-card"><span>Inventory value</span><strong>${money(d.stockValue)}</strong><small>${d.inventory} catalogued items</small></div>
    <div class="metric-card ${d.low?'metric-warn':''}"><span>Low stock</span><strong>${d.low}</strong><small>items need replenishment</small></div>
    <div class="metric-card ${d.expired?'metric-danger':''}"><span>Expiry</span><strong>${d.expired+d.expiring}</strong><small>${d.expired} expired · ${d.expiring} approaching</small></div>
    <div class="metric-card"><span>Open procurement</span><strong>${d.pending}</strong><small>${d.requested} requested · ${d.delayed} delayed</small></div>
    <div class="metric-card"><span>This month</span><strong>${money(d.monthSpend)}</strong><small>ordered value</small></div>
    <div class="metric-card"><span>Active containers</span><strong>${d.containers}</strong><small>physical stock ledger</small></div>
    <div class="metric-card"><span>Equipment</span><strong>${db.equipment.length}</strong><small>${db.equipment.filter(e=>e.status==='AVAILABLE').length} available</small></div>
    <div class="metric-card"><span>Samples</span><strong>${db.samples.length}</strong><small>${db.locations.length} storage locations</small></div>
  </div>
  <div class="dashboard-grid">
    <section class="panel attention-panel"><div class="panel-head"><h2>Needs attention</h2><button id="seeAllNotifications">View all</button></div>${notes.length?notes.map(notificationRow).join(''):'<div class="empty-state">No unacknowledged alerts.</div>'}</section>
    <section class="panel"><h2>Procurement status</h2>${Object.keys(statusCounts).length?Object.entries(statusCounts).map(([k,v])=>`<div class="bar-row"><div><span>${esc(k)}</span><b>${v}</b></div><div class="bar"><i style="width:${Math.max(6,(v/maxStatus)*100)}%"></i></div></div>`).join(''):'<div class="empty-state">No procurement records yet.</div>'}</section>
    <section class="panel"><h2>Recent usage</h2>${db.usage.slice(0,7).map(u=>`<div class="activity-row"><div><b>${esc(u.item_name||'Inventory use')}</b><div class="sub">${esc(u.project||'General')} · ${new Date(u.created_at).toLocaleString()}</div></div><strong>${u.quantity} ${esc(u.unit||'')}</strong></div>`).join('')||'<div class="empty-state">No usage recorded yet.</div>'}</section>
    <section class="panel"><h2>Low-stock shortlist</h2>${db.inventory.filter(low).slice(0,7).map(x=>`<button class="list-link" data-detail="${x.id}"><span><b>${esc(x.name)}</b><small>${esc(x.item_code)}</small></span><strong class="danger">${x.current_stock}/${x.min_stock} ${esc(x.unit)}</strong></button>`).join('')||'<div class="empty-state">All items are above their minimum stock level.</div>'}</section>
  </div>`;
  $('#dashRequest').onclick=requestModal;if(admin())$('#dashAddItem').onclick=itemModal;$('#seeAllNotifications').onclick=()=>setPage('notifications');
  $$('[data-detail]').forEach(b=>b.onclick=()=>openInventoryDetail(+b.dataset.detail));
  $$('[data-ack]').forEach(b=>b.onclick=()=>ackOne(b.dataset.ack));
  $$('[data-open-notification]').forEach(b=>b.onclick=()=>openNotificationEntity(b.dataset.openNotification));
}

function inventory(){
  const rows=db.inventory.filter(x=>!search||JSON.stringify(x).toLowerCase().includes(search));
  $('#page').innerHTML=`<div class="page-head"><div><h1>Laboratory Inventory</h1><p>Shared Supabase inventory with container tracking and RLS permissions.</p></div>${admin()?'<button class="primary" id="addItem">+ Add Item</button>':''}</div>${stats()}${alertStrip()}<div class="toolbar"><input id="invSearch" value="${esc(search)}" placeholder="Search item, SKU, CAS..."><button id="exportCsv">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>CAS</th><th>Stock</th><th>Storage</th><th>Expiry</th><th>Project</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable-row" data-row-detail="${x.id}"><td><b>${esc(x.name)}</b><div class="sub">${esc(x.item_code)} · ${esc(x.sku||'')}</div></td><td>${x.cas?esc(x.cas):'—'}</td><td><b class="${low(x)?'danger':''}">${x.current_stock} ${esc(x.unit)}</b><div class="sub">min ${x.min_stock}</div></td><td>${esc(x.storage||'—')}</td><td>${dateLabel(x.expiry_date)}</td><td>${esc(x.project||'—')}</td><td><div class="actions"><button data-view="${x.id}">View</button><button data-use="${x.id}">Use</button><button data-cont="${x.id}">Containers</button>${admin()?`<button data-adj="${x.id}">Adjust</button><button data-doc="${x.id}">Docs</button>`:''}<button data-lab="${x.id}">Label</button></div></td></tr>`).join('')}</tbody></table></div>`;
  if(admin())$('#addItem').onclick=itemModal;$('#exportCsv').onclick=()=>dl(csv(),'labb_inventory.csv','text/csv');if($('#openAlerts'))$('#openAlerts').onclick=()=>setPage('notifications');
  $('#invSearch').oninput=e=>{search=e.target.value.toLowerCase();$('#search').value=e.target.value;inventory()};
  $$('[data-view]').forEach(b=>b.onclick=e=>{e.stopPropagation();openInventoryDetail(+b.dataset.view)});$$('[data-row-detail]').forEach(r=>r.onclick=e=>{if(!e.target.closest('button'))openInventoryDetail(+r.dataset.rowDetail)});$$('[data-use]').forEach(b=>b.onclick=e=>{e.stopPropagation();usageModal(+b.dataset.use)});$$('[data-cont]').forEach(b=>b.onclick=e=>{e.stopPropagation();containersModal(+b.dataset.cont)});$$('[data-adj]').forEach(b=>b.onclick=e=>{e.stopPropagation();adjustModal(+b.dataset.adj)});$$('[data-doc]').forEach(b=>b.onclick=e=>{e.stopPropagation();documentsModal('inventory',b.dataset.doc)});$$('[data-lab]').forEach(b=>b.onclick=e=>{e.stopPropagation();printItem(+b.dataset.lab)});
}

function openInventoryDetail(id){selectedInventoryId=id;page='inventory-detail';$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page==='inventory'));render()}
function inventoryDetail(){
  const x=db.inventory.find(i=>i.id===selectedInventoryId);if(!x){setPage('inventory');return}
  const cs=db.containers.filter(c=>c.inventory_id===x.id).sort((a,b)=>String(a.expiry_date||'9999').localeCompare(String(b.expiry_date||'9999')));
  const usage=db.usage.filter(u=>u.inventory_id===x.id).slice(0,20);
  const active=cs.filter(c=>c.status==='ACTIVE'&&Number(c.quantity_remaining)>0), expiring=active.filter(c=>{const e=expiry(c.expiry_date,db.lab?.expiry_notice_days||90);return e?.warning||e?.expired});
  $('#page').innerHTML=`<div class="breadcrumb"><button id="backInventory">Inventory</button><span>›</span><span>${esc(x.name)}</span></div><div class="detail-hero"><div><div class="eyebrow">${esc(x.category||'Inventory')} · ${esc(x.item_code)}</div><h1>${esc(x.name)}</h1><p>${esc(x.manufacturer||'')} ${x.catalogue_number?`· ${esc(x.catalogue_number)}`:''}</p></div><div class="stock-hero ${low(x)?'stock-low':''}"><span>Available stock</span><strong>${x.current_stock} ${esc(x.unit)}</strong><small>Minimum ${x.min_stock} ${esc(x.unit)}</small></div></div>
  <div class="detail-actions"><button class="primary" id="detailUse">Record usage</button><button id="detailContainers">Containers</button><button id="detailDocs">Documents</button><button id="detailLabel">Print label</button>${admin()?'<button id="detailAdjust">Adjust stock</button>':''}</div>
  ${expiring.length?`<div class="alerts"><b>⚠ ${expiring.length} active container${expiring.length===1?'':'s'} have expiry attention.</b><button id="detailNotifications">Open notifications</button></div>`:''}
  <div class="detail-grid"><section class="panel"><h2>Item profile</h2><div class="meta-grid">${[['SKU',x.sku],['CAS',x.cas],['Formula',x.formula],['Grade',x.grade],['Storage',x.storage],['Project',x.project],['Unit cost',money(x.unit_cost)],['Reference expiry',dateLabel(x.expiry_date)]].map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v||'—')}</b></div>`).join('')}</div>${x.notes?`<div class="detail-notes"><span>Notes</span><p>${esc(x.notes)}</p></div>`:''}</section>
  <section class="panel"><div class="panel-head"><h2>Container / lot ledger</h2><span class="pill">${active.length} active</span></div><div class="table-wrap"><table><thead><tr><th>Container</th><th>Lot</th><th>Remaining</th><th>Received</th><th>Expiry</th><th>Status</th></tr></thead><tbody>${cs.map(c=>{const e=expiry(c.expiry_date,db.lab?.expiry_notice_days||90);return `<tr><td><b>${esc(c.container_code)}</b></td><td>${esc(c.lot_number||'—')}</td><td>${c.quantity_remaining} ${esc(c.unit)}</td><td>${dateLabel(c.received_date)}</td><td class="${e?.expired?'danger':e?.warning?'warning-text':''}">${dateLabel(c.expiry_date)}</td><td>${chip(c.status)}</td></tr>`}).join('')||'<tr><td colspan="6">No containers yet.</td></tr>'}</tbody></table></div></section>
  <section class="panel"><h2>Recent consumption</h2>${usage.map(u=>`<div class="activity-row"><div><b>${u.quantity} ${esc(u.unit)} · ${esc(u.project||'General')}</b><div class="sub">${esc(u.purpose||'No purpose recorded')} · ${new Date(u.created_at).toLocaleString()}</div></div></div>`).join('')||'<div class="empty-state">No usage recorded for this item.</div>'}</section>
  <section class="panel"><h2>Stock health</h2><div class="health-list"><div><span>Current / minimum</span><b class="${low(x)?'danger':''}">${x.current_stock} / ${x.min_stock} ${esc(x.unit)}</b></div><div><span>Active lots</span><b>${active.length}</b></div><div><span>Expiry attention</span><b>${expiring.length}</b></div><div><span>Estimated stock value</span><b>${money(Number(x.current_stock||0)*Number(x.unit_cost||0))}</b></div></div></section></div>`;
  $('#backInventory').onclick=()=>setPage('inventory');$('#detailUse').onclick=()=>usageModal(x.id);$('#detailContainers').onclick=()=>containersModal(x.id);$('#detailDocs').onclick=()=>documentsModal('inventory',x.id);$('#detailLabel').onclick=()=>printItem(x.id);if(admin())$('#detailAdjust').onclick=()=>adjustModal(x.id);if($('#detailNotifications'))$('#detailNotifications').onclick=()=>setPage('notifications');
}

function procurement(){const rows=db.procurement.filter(r=>!search||JSON.stringify(r).toLowerCase().includes(search));$('#page').innerHTML=`<div class="page-head"><div><h1>Procurement</h1><p>Request → approve → order → receive → reconcile → close.</p></div><button class="primary" id="newReq2">+ New Request</button></div>${stats()}<div class="thread">${rows.map(r=>{const v=db.vendors.find(x=>x.id===r.vendor_id);const reqBy=db.profiles.find(x=>x.id===r.requested_by);return `<article class="request"><div class="req-head"><div><b>${esc(v?.name||reqBy?.display_name||'Lab member')}</b><div class="sub">Request #${r.id} · ${new Date(r.created_at).toLocaleDateString()}</div></div>${chip(r.status)}</div><span class="project">${esc(r.project||'General')}</span>${r.items.map(i=>{const inv=db.inventory.find(x=>x.id===i.inventory_id);return `<div class="itemrow"><span>${esc(inv?.name||i.item_name||'Item')}</span><b>${i.received_quantity||0}/${i.quantity} ${esc(i.unit)}</b></div>`}).join('')}<div class="sub">Needed ${dateLabel(r.needed_by)} ${r.po_number?`· ${esc(r.po_number)}`:''}${r.approved_at?` · approved ${new Date(r.approved_at).toLocaleDateString()}`:''}</div><div class="actions" style="margin-top:10px">${admin()&&r.status==='Requested'?`<button class="primary" data-approve="${r.id}">Approve</button>`:''}${admin()&&r.status==='Approved'?`<button data-order="${r.id}">Create Order</button>`:''}${admin()&&['Ordered','Partial','Delayed'].includes(r.status)?`<button data-rec="${r.id}">Receive</button>`:''}${admin()&&r.status==='Delivered'?`<button data-inv="${r.id}">Invoice</button><button data-close="${r.id}">Close</button>`:''}<button data-docreq="${r.id}">Docs</button>${r.po_number?`<button data-po="${r.id}">Print PO</button>`:''}</div></article>`}).join('')}</div>`;$('#newReq2').onclick=requestModal;$$('[data-approve]').forEach(b=>b.onclick=()=>approveModal(+b.dataset.approve));$$('[data-order]').forEach(b=>b.onclick=()=>orderModal(+b.dataset.order));$$('[data-rec]').forEach(b=>b.onclick=()=>receiveModal(+b.dataset.rec));$$('[data-inv]').forEach(b=>b.onclick=()=>invoiceModal(+b.dataset.inv));$$('[data-close]').forEach(b=>b.onclick=async()=>{try{await api.closeRequest(+b.dataset.close);toast('Closed');await refresh()}catch(e){fail(e)}});$$('[data-docreq]').forEach(b=>b.onclick=()=>documentsModal('request',b.dataset.docreq));$$('[data-po]').forEach(b=>b.onclick=()=>printPO(+b.dataset.po))}
function approveModal(id){modal('Approve procurement request',`<label>Approval note<textarea id="ap_note" placeholder="Optional approval note"></textarea></label>`,async()=>{await api.approveRequest(id,$('#ap_note').value.trim());toast('Request approved');await refresh()},'Approve')}
function vendors(){const rows=db.vendors.filter(v=>!search||JSON.stringify(v).toLowerCase().includes(search));$('#page').innerHTML=`<div class="page-head"><div><h1>Vendors</h1><p>Supplier contacts and procurement partners.</p></div>${admin()?'<button class="primary" id="addVendor">+ Add Vendor</button>':''}</div><div class="vendor-grid">${rows.map(v=>`<div class="card"><h3>${esc(v.name)}</h3><p>${esc(v.contact||'')}</p><div class="sub">${esc(v.email||'')}<br>${esc(v.phone||'')}<br>${esc(v.city||'')}<br>★ ${v.rating||'—'}</div></div>`).join('')}</div>`;if(admin())$('#addVendor').onclick=vendorModal}

function notificationRow(n){const badge=n.severity==='critical'?'Critical':n.severity==='warning'?'Warning':'Info';return `<div class="notification-row ${n.acknowledged?'is-acknowledged':''} severity-${n.severity}"><div class="notification-icon">${n.severity==='critical'?'!':n.severity==='warning'?'⚠':'i'}</div><div class="notification-copy"><div><span class="severity-badge">${badge}</span><b>${esc(n.title)}</b></div><div class="sub">${esc(n.body)}</div></div><div class="notification-actions"><button data-open-notification="${esc(n.key)}">Open</button>${n.acknowledged?'<span class="ack-label">Acknowledged</span>':`<button data-ack="${esc(n.key)}" class="primary">Acknowledge</button>`}</div></div>`}
function notificationCenter(){const all=buildNotifications(), unread=all.filter(n=>!n.acknowledged), acknowledged=all.filter(n=>n.acknowledged);$('#page').innerHTML=`<div class="page-head"><div><h1>Notification Center</h1><p>Operational alerts derived from live inventory and procurement data.</p></div>${unread.length?'<button id="ackAll">Acknowledge all</button>':''}</div><div class="notification-summary"><div><strong>${unread.length}</strong><span>Unacknowledged</span></div><div><strong>${all.filter(n=>!n.acknowledged&&n.severity==='critical').length}</strong><span>Critical</span></div><div><strong>${all.filter(n=>!n.acknowledged&&n.type==='low-stock').length}</strong><span>Low stock</span></div><div><strong>${all.filter(n=>!n.acknowledged&&n.type==='expiry').length}</strong><span>Expiry</span></div></div><section class="panel"><h2>Active</h2>${unread.map(notificationRow).join('')||'<div class="empty-state">Everything is acknowledged. New alerts will appear automatically as data changes.</div>'}</section>${acknowledged.length?`<section class="panel acknowledged-panel"><h2>Acknowledged</h2>${acknowledged.slice(0,25).map(notificationRow).join('')}</section>`:''}`;$$('[data-ack]').forEach(b=>b.onclick=()=>ackOne(b.dataset.ack));$$('[data-open-notification]').forEach(b=>b.onclick=()=>openNotificationEntity(b.dataset.openNotification));if($('#ackAll'))$('#ackAll').onclick=async()=>{try{for(const n of unread)await api.ackNotification(profile.lab_id,n.key);toast('Notifications acknowledged');await refresh()}catch(e){fail(e)}}}
async function ackOne(key){try{await api.ackNotification(profile.lab_id,key);toast('Acknowledged');await refresh()}catch(e){fail(e)}}
function openNotificationEntity(key){const n=buildNotifications().find(x=>x.key===key);if(!n)return;if(n.entity==='inventory')openInventoryDetail(Number(n.entityId));else if(n.entity==='procurement'){page='procurement';search=String(n.entityId);$('#search').value=search;$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page==='procurement'));render();}else if(n.entity==='equipment')setPage('equipment');else if(n.entity==='sample')setPage('samples');}

function analytics(){const cats={},projects={};db.inventory.forEach(x=>cats[x.category]=(cats[x.category]||0)+Number(x.current_stock||0)*Number(x.unit_cost||0));db.procurement.forEach(r=>projects[r.project]=(projects[r.project]||0)+Number(r.ordered_total||0));const reorder=db.inventory.filter(low).map(x=>({...x,recommended_order:Math.max(1,Math.ceil(Number(x.min_stock)*2-Number(x.current_stock)))}));$('#page').innerHTML=`<div class="page-head"><div><h1>Analytics</h1><p>Live summaries from the shared Supabase dataset.</p></div></div>${stats()}<div class="grid"><section class="panel"><h2>Reorder suggestions</h2>${reorder.map(x=>`<button class="list-link" data-detail="${x.id}"><span><b>${esc(x.name)}</b><small>${x.current_stock}/${x.min_stock} ${esc(x.unit)}</small></span><strong>Order ${x.recommended_order}</strong></button>`).join('')||'No suggestions'}</section><section class="panel"><h2>Inventory value</h2>${Object.entries(cats).map(([k,v])=>`<div class="auditrow"><b>${esc(k)}</b><span style="float:right">${money(v)}</span></div>`).join('')}</section><section class="panel"><h2>Project spend</h2>${Object.entries(projects).map(([k,v])=>`<div class="auditrow"><b>${esc(k)}</b><span style="float:right">${money(v)}</span></div>`).join('')}</section><section class="panel"><h2>Usage</h2>${db.usage.slice(0,15).map(u=>`<div class="auditrow"><b>${esc(u.item_name||'Inventory use')}</b><span style="float:right">${u.quantity} ${esc(u.unit||'')}</span><div class="sub">${esc(u.project||'')} · ${esc(u.purpose||'')}</div></div>`).join('')||'No usage yet'}</section></div>`;$$('[data-detail]').forEach(b=>b.onclick=()=>openInventoryDetail(+b.dataset.detail))}
function settings(){$('#page').innerHTML=`<div class="page-head"><div><h1>Settings</h1><p>Supabase connection, laboratory profile and audit history.</p></div><button id="logout">Sign out</button></div><div class="grid"><section class="panel"><h2>Account</h2><b>${esc(profile.display_name||user.email)}</b><p class="sub">${esc(user.email)} · ${esc(profile.role)}</p><div class="notice">Authorization is enforced by Supabase Row Level Security, not by hidden buttons in this page.</div></section><section class="panel"><h2>Laboratory</h2><b>${esc(db.lab?.name||'')}</b><p class="sub">${esc(db.lab?.address||'')}</p>${admin()?'<div class="actions"><button id="editLab">Edit</button><button id="inviteUser">Invite user</button></div>':''}</section><section class="panel"><h2>Backend</h2><p><b>Supabase connected</b></p><p class="sub">Postgres database · Auth · Storage · Realtime</p><p class="sub">Production release · Version ${VERSION}</p></section><section class="panel audit"><h2>Audit log</h2>${db.audit.map(a=>`<div class="auditrow"><b>${esc(a.action)}</b> · ${esc(a.entity_type)} #${esc(a.entity_id||'')}<div class="sub">${new Date(a.created_at).toLocaleString()} · ${esc(a.actor_email||a.actor_id||'system')}</div></div>`).join('')||'No audit events'}</section></div>`;$('#logout').onclick=async()=>{await api.signOut();showLogin()};if(admin()){ $('#editLab').onclick=labModal; $('#inviteUser').onclick=inviteUserModal }}


function equipmentPage(){
  const rows=db.equipment.filter(e=>!search||JSON.stringify(e).toLowerCase().includes(search));
  $('#page').innerHTML=`<div class="page-head"><div><h1>Equipment</h1><p>Instrument registry, bookings, calibration and maintenance.</p></div>${admin()?'<button class="primary" id="addEquipment">+ Equipment</button>':''}</div><div class="dashboard-metrics"><div class="metric-card"><span>Equipment</span><strong>${db.equipment.length}</strong><small>registered instruments</small></div><div class="metric-card"><span>Available</span><strong>${db.equipment.filter(e=>e.status==='AVAILABLE').length}</strong><small>ready for use</small></div><div class="metric-card metric-warn"><span>Due ≤30d</span><strong>${db.equipment.filter(e=>[e.calibration_due,e.maintenance_due].some(d=>{const x=expiry(d,30);return x?.warning||x?.expired})).length}</strong><small>service attention</small></div></div><div class="vendor-grid">${rows.map(e=>{const bookings=db.bookings.filter(b=>b.equipment_id===e.id&&b.status==='CONFIRMED').slice(0,2);return `<div class="card"><div class="req-head"><div><h3>${esc(e.name)}</h3><div class="sub">${esc(e.equipment_code)} · ${esc(e.model||'')}</div></div>${chip(e.status)}</div><p>${esc(e.location||'')}</p><div class="meta-grid"><div><span>Calibration</span><b>${dateLabel(e.calibration_due)}</b></div><div><span>Maintenance</span><b>${dateLabel(e.maintenance_due)}</b></div></div><div class="sub" style="margin-top:10px">${bookings.length?bookings.map(b=>`${new Date(b.start_at).toLocaleString()} · ${esc(b.purpose||'Booked')}`).join('<br>'):'No upcoming bookings loaded.'}</div><div class="actions" style="margin-top:12px"><button data-book="${e.id}">Book</button>${admin()?`<button data-service="${e.id}">Service</button><button data-equip-edit="${e.id}">Status</button>`:''}<button data-equip-doc="${e.id}">Docs</button></div></div>`}).join('')||'<div class="empty-state">No equipment registered.</div>'}</div>`;
  if(admin())$('#addEquipment').onclick=equipmentModal;$$('[data-book]').forEach(b=>b.onclick=()=>bookingModal(+b.dataset.book));$$('[data-service]').forEach(b=>b.onclick=()=>serviceModal(+b.dataset.service));$$('[data-equip-edit]').forEach(b=>b.onclick=()=>equipmentStatusModal(+b.dataset.equipEdit));$$('[data-equip-doc]').forEach(b=>b.onclick=()=>documentsModal('equipment',b.dataset.equipDoc));
}
function equipmentModal(){modal('Add equipment',`<div class="formgrid"><label>Name<input id="eq_name"></label><label>Code<input id="eq_code" placeholder="EQ-001"></label><label>Model<input id="eq_model"></label><label>Serial number<input id="eq_serial"></label><label>Location<input id="eq_location"></label><label>Status<select id="eq_status"><option>AVAILABLE</option><option>OUT_OF_SERVICE</option><option>RETIRED</option></select></label><label>Calibration due<input id="eq_cal" type="date"></label><label>Maintenance due<input id="eq_main" type="date"></label><label class="full">Notes<textarea id="eq_notes"></textarea></label></div>`,async()=>{if(!$('#eq_name').value.trim())throw Error('Name required');await api.addEquipment(profile.lab_id,{name:$('#eq_name').value.trim(),equipment_code:$('#eq_code').value.trim()||`EQ-${Date.now().toString().slice(-6)}`,model:$('#eq_model').value.trim(),serial_number:$('#eq_serial').value.trim(),location:$('#eq_location').value.trim(),status:$('#eq_status').value,calibration_due:$('#eq_cal').value||null,maintenance_due:$('#eq_main').value||null,notes:$('#eq_notes').value.trim()});toast('Equipment added');await refresh()})}
function equipmentStatusModal(id){const e=db.equipment.find(x=>x.id===id);modal(`Update ${e.name}`,`<div class="formgrid"><label>Status<select id="eqs_status">${['AVAILABLE','OUT_OF_SERVICE','RETIRED'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Calibration due<input id="eqs_cal" type="date" value="${esc(e.calibration_due||'')}"></label><label>Maintenance due<input id="eqs_main" type="date" value="${esc(e.maintenance_due||'')}"></label></div>`,async()=>{await api.updateEquipment(id,{status:$('#eqs_status').value,calibration_due:$('#eqs_cal').value||null,maintenance_due:$('#eqs_main').value||null});toast('Equipment updated');await refresh()})}
function bookingModal(equipmentId){const e=db.equipment.find(x=>x.id===equipmentId);const now=new Date(),later=new Date(now.getTime()+3600000);const local=d=>new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);modal(`Book ${e.name}`,`<div class="formgrid"><label>Start<input id="bk_start" type="datetime-local" value="${local(now)}"></label><label>End<input id="bk_end" type="datetime-local" value="${local(later)}"></label><label class="full">Purpose<input id="bk_purpose"></label></div>`,async()=>{const a=$('#bk_start').value,b=$('#bk_end').value;if(!a||!b||new Date(b)<=new Date(a))throw Error('Choose a valid time range');await api.addBooking(profile.lab_id,{equipment_id:equipmentId,user_id:user.id,start_at:new Date(a).toISOString(),end_at:new Date(b).toISOString(),purpose:$('#bk_purpose').value.trim(),status:'CONFIRMED'});toast('Booking saved');await refresh()},'Book')}
function serviceModal(equipmentId){const e=db.equipment.find(x=>x.id===equipmentId);modal(`Service ${e.name}`,`<div class="formgrid"><label>Type<select id="sv_type"><option>CALIBRATION</option><option>MAINTENANCE</option><option>REPAIR</option></select></label><label>Service date<input id="sv_date" type="date" value="${today()}"></label><label>Next due<input id="sv_due" type="date"></label><label>Provider<input id="sv_provider"></label><label class="full">Notes<textarea id="sv_notes"></textarea></label></div>`,async()=>{const type=$('#sv_type').value,due=$('#sv_due').value||null;await api.addServiceLog(profile.lab_id,{equipment_id:equipmentId,service_type:type,serviced_at:$('#sv_date').value, next_due:due,provider:$('#sv_provider').value.trim(),notes:$('#sv_notes').value.trim(),performed_by:user.id});const patch={};if(type==='CALIBRATION')patch.calibration_due=due;if(type==='MAINTENANCE')patch.maintenance_due=due;if(Object.keys(patch).length)await api.updateEquipment(equipmentId,patch);toast('Service logged');await refresh()},'Save service')}

function samplesPage(){
 const rows=db.samples.filter(s=>!search||JSON.stringify(s).toLowerCase().includes(search));
 const locationName=id=>db.locations.find(l=>l.id===id)?.name||'Unassigned';
 $('#page').innerHTML=`<div class="page-head"><div><h1>Samples & Storage</h1><p>Freezer, rack, box and slot-aware sample registry.</p></div><div class="actions">${admin()?'<button id="addLocation">+ Location</button>':''}<button class="primary" id="addSample">+ Sample</button></div></div><div class="dashboard-metrics"><div class="metric-card"><span>Samples</span><strong>${db.samples.length}</strong><small>registered records</small></div><div class="metric-card"><span>Locations</span><strong>${db.locations.length}</strong><small>storage nodes</small></div><div class="metric-card metric-warn"><span>Expiring ≤30d</span><strong>${db.samples.filter(s=>{const x=expiry(s.expiry_date,30);return s.status==='ACTIVE'&&(x?.warning||x?.expired)}).length}</strong><small>sample attention</small></div></div><div class="table-wrap"><table><thead><tr><th>Sample</th><th>Project</th><th>Location</th><th>Slot</th><th>Quantity</th><th>Expiry</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.name)}</b><div class="sub">${esc(s.sample_code)}</div></td><td>${esc(s.project||'')}</td><td>${esc(locationName(s.location_id))}</td><td>${esc(s.slot||'—')}</td><td>${s.quantity} ${esc(s.unit)}</td><td>${dateLabel(s.expiry_date)}</td><td>${chip(s.status)}</td><td><div class="actions"><button data-sample-status="${s.id}">Update</button><button data-sample-doc="${s.id}">Docs</button></div></td></tr>`).join('')}</tbody></table></div>`;
 if(admin())$('#addLocation').onclick=locationModal;$('#addSample').onclick=sampleModal;$$('[data-sample-status]').forEach(b=>b.onclick=()=>sampleStatusModal(+b.dataset.sampleStatus));$$('[data-sample-doc]').forEach(b=>b.onclick=()=>documentsModal('sample',b.dataset.sampleDoc));
}
function locationModal(){const opts=db.locations.map(l=>`<option value="${l.id}">${esc(l.name)} (${esc(l.location_type)})</option>`).join('');modal('Add storage location',`<div class="formgrid"><label>Name<input id="loc_name"></label><label>Code<input id="loc_code"></label><label>Type<select id="loc_type"><option>ROOM</option><option>FREEZER</option><option>SHELF</option><option>RACK</option><option>BOX</option></select></label><label>Parent<select id="loc_parent"><option value="">None</option>${opts}</select></label></div>`,async()=>{if(!$('#loc_name').value.trim())throw Error('Name required');await api.addLocation(profile.lab_id,{name:$('#loc_name').value.trim(),code:$('#loc_code').value.trim()||`LOC-${Date.now().toString().slice(-7)}`,location_type:$('#loc_type').value,parent_id:$('#loc_parent').value||null});toast('Location added');await refresh()})}
function sampleModal(){const opts=db.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('');modal('Add sample',`<div class="formgrid"><label>Name<input id="sm_name"></label><label>Sample code<input id="sm_code" placeholder="SMP-001"></label><label>Project<input id="sm_project" value="General"></label><label>Location<select id="sm_loc"><option value="">Unassigned</option>${opts}</select></label><label>Slot<input id="sm_slot" placeholder="A1"></label><label>Quantity<input id="sm_qty" type="number" step="any" value="1"></label><label>Unit<input id="sm_unit" value="vials"></label><label>Expiry<input id="sm_exp" type="date"></label><label class="full">Notes<textarea id="sm_notes"></textarea></label></div>`,async()=>{if(!$('#sm_name').value.trim())throw Error('Name required');await api.addSample(profile.lab_id,{sample_code:$('#sm_code').value.trim()||`SMP-${Date.now().toString().slice(-7)}`,name:$('#sm_name').value.trim(),project:$('#sm_project').value.trim(),owner_id:user.id,location_id:$('#sm_loc').value||null,slot:$('#sm_slot').value.trim(),quantity:+$('#sm_qty').value||0,unit:$('#sm_unit').value.trim(),status:'ACTIVE',expiry_date:$('#sm_exp').value||null,notes:$('#sm_notes').value.trim()});toast('Sample added');await refresh()})}
function sampleStatusModal(id){const s=db.samples.find(x=>x.id===id);modal(`Update ${s.name}`,`<div class="formgrid"><label>Status<select id="sms_status">${['ACTIVE','CONSUMED','DISPOSED','ARCHIVED'].map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Quantity<input id="sms_qty" type="number" step="any" value="${s.quantity}"></label></div>`,async()=>{await api.updateSample(id,{status:$('#sms_status').value,quantity:+$('#sms_qty').value||0});toast('Sample updated');await refresh()})}

function teamPage(){if(!admin()){setPage('dashboard');toast('Admin required');return}$('#page').innerHTML=`<div class="page-head"><div><h1>Team & Permissions</h1><p>Lab membership and backend-enforced roles.</p></div><button class="primary" id="teamInvite">+ Invite user</button></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody>${db.profiles.map(p=>`<tr><td><b>${esc(p.display_name)}</b>${p.id===user.id?'<div class="sub">You</div>':''}</td><td>${esc(p.email||'—')}</td><td>${chip(p.role)}</td><td>${chip(p.active===false?'INACTIVE':'ACTIVE')}</td><td>${new Date(p.created_at).toLocaleDateString()}</td><td><div class="actions">${p.id!==user.id?`<button data-team-role="${p.id}">Role</button><button data-team-active="${p.id}">${p.active===false?'Reactivate':'Deactivate'}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;$('#teamInvite').onclick=inviteUserModal;$$('[data-team-role]').forEach(b=>b.onclick=()=>teamRoleModal(b.dataset.teamRole));$$('[data-team-active]').forEach(b=>b.onclick=async()=>{const p=db.profiles.find(x=>x.id===b.dataset.teamActive);try{await api.updateTeamMember(p.id,{active:p.active===false});toast('User status updated');await refresh()}catch(e){fail(e)}})}
function teamRoleModal(id){const p=db.profiles.find(x=>x.id===id);modal(`Role · ${p.display_name}`,`<label>Role<select id="tm_role"><option value="member" ${p.role==='member'?'selected':''}>Member</option><option value="admin" ${p.role==='admin'?'selected':''}>Admin</option></select></label>`,async()=>{await api.updateTeamMember(id,{role:$('#tm_role').value});toast('Role updated');await refresh()})}

async function cameraScan(){
 if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Camera barcode detection is not supported here. Use manual entry or a keyboard-wedge scanner.');return}
 const formats=await BarcodeDetector.getSupportedFormats();const detector=new BarcodeDetector({formats:formats.filter(x=>['qr_code','code_128','code_39','ean_13','ean_8'].includes(x))});
 $('#modal').innerHTML=`<div class="modalbg"><div class="modalbox"><div class="modalhead"><b>Camera scanner</b><button id="camClose">✕</button></div><div class="modalbody"><video id="camVideo" autoplay playsinline style="width:100%;border-radius:14px;background:#111"></video><div class="sub">Point the camera at a QR or barcode label.</div></div></div></div>`;
 const video=$('#camVideo');let stream;let stopped=false;const stop=()=>{stopped=true;stream?.getTracks().forEach(t=>t.stop());$('#modal').innerHTML=''};$('#camClose').onclick=stop;
 try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;const loop=async()=>{if(stopped)return;try{const found=await detector.detect(video);if(found.length){const raw=found[0].rawValue;stop();resolveScannedCode(raw);return}}catch{}requestAnimationFrame(loop)};requestAnimationFrame(loop)}catch(e){stop();fail(e)}
}
function resolveScannedCode(raw){let c=String(raw||'').trim();c=c.replace(/^labb:\/\/(inventory|container)\//,'');const i=db.inventory.find(x=>x.item_code===c||x.sku===c),ct=db.containers.find(x=>x.container_code===c),s=db.samples.find(x=>x.sample_code===c),eq=db.equipment.find(x=>x.equipment_code===c);if(i){openInventoryDetail(i.id);toast(i.name)}else if(ct){const inv=db.inventory.find(x=>x.id===ct.inventory_id);containersModal(inv.id);toast(ct.container_code)}else if(s){setPage('samples');search=s.sample_code.toLowerCase();$('#search').value=s.sample_code;render();toast(s.name)}else if(eq){setPage('equipment');search=eq.equipment_code.toLowerCase();$('#search').value=eq.equipment_code;render();toast(eq.name)}else toast('Code not found')}
function itemModal(){modal('Add inventory item',`<div class="formgrid"><label>Name<input id="f_name" required></label><label>Category<input id="f_category" value="Chemical"></label><label>SKU<input id="f_sku"></label><label>CAS<input id="f_cas"></label><label>Minimum stock<input id="f_min" type="number" step="any" value="1"></label><label>Unit<input id="f_unit" value="bottles"></label><label>Storage<input id="f_storage"></label><label>Expiry<input id="f_expiry" type="date"></label><label>Project<input id="f_project" value="General"></label><label>Unit cost<input id="f_cost" type="number" step="0.01" value="0"></label><label class="full">Manufacturer<input id="f_manu"></label></div>`,async()=>{if(!$('#f_name').value.trim())throw Error('Name required');await api.addInventory(profile.lab_id,{name:$('#f_name').value.trim(),category:$('#f_category').value.trim(),sku:$('#f_sku').value.trim(),cas:$('#f_cas').value.trim()||null,min_stock:+$('#f_min').value||0,unit:$('#f_unit').value.trim(),storage:$('#f_storage').value.trim(),expiry_date:$('#f_expiry').value||null,project:$('#f_project').value.trim(),unit_cost:+$('#f_cost').value||0,manufacturer:$('#f_manu').value.trim()});toast('Item added');await refresh()})}
function vendorModal(){modal('Add vendor',`<div class="formgrid"><label>Name<input id="v_name"></label><label>Contact<input id="v_contact"></label><label>Email<input id="v_email" type="email"></label><label>Phone<input id="v_phone"></label><label>City<input id="v_city"></label><label>Rating<input id="v_rating" type="number" min="0" max="5" step="0.1" value="4"></label></div>`,async()=>{if(!$('#v_name').value.trim())throw Error('Vendor name required');await api.addVendor(profile.lab_id,{name:$('#v_name').value.trim(),contact:$('#v_contact').value.trim(),email:$('#v_email').value.trim(),phone:$('#v_phone').value.trim(),city:$('#v_city').value.trim(),rating:+$('#v_rating').value||null});toast('Vendor added');await refresh()})}
function requestModal(){if(!db.inventory.length)return toast('Add inventory first');const opts=db.inventory.map(x=>`<option value="${x.id}">${esc(x.name)} (${esc(x.unit)})</option>`).join('');modal('New procurement request',`<div class="formgrid"><label>Project<input id="r_project" value="General"></label><label>Needed by<input id="r_need" type="date"></label><label class="full">Item<select id="r_item">${opts}</select></label><label>Quantity<input id="r_qty" type="number" min="0.0001" step="any" value="1"></label><label>Justification<input id="r_note"></label></div>`,async()=>{const inv=db.inventory.find(x=>x.id===+$('#r_item').value);await api.createRequest(profile.lab_id,user.id,{project:$('#r_project').value.trim(),needed_by:$('#r_need').value||null,status:'Requested',justification:$('#r_note').value.trim()},[{inventory_id:inv.id,quantity:+$('#r_qty').value,received_quantity:0,unit:inv.unit}]);toast('Request created');await refresh()},'Create request')}
function orderModal(id){const vo=db.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('');modal('Create order',`<div class="formgrid"><label>Vendor<select id="o_vendor">${vo}</select></label><label>Expected date<input id="o_date" type="date"></label><label class="full">Order total<input id="o_total" type="number" min="0" step="0.01"></label></div>`,async()=>{await api.placeOrder(id,+$('#o_vendor').value,$('#o_date').value,+$('#o_total').value);toast('Order created');await refresh()},'Place order')}
function receiveModal(id){const r=db.procurement.find(x=>x.id===id);modal('Receive items',`<div class="formgrid">${r.items.map(i=>{const inv=db.inventory.find(x=>x.id===i.inventory_id),remain=Number(i.quantity)-Number(i.received_quantity||0);return `<div class="full panel"><b>${esc(inv?.name||'Item')}</b><div class="formgrid"><label>Receive now<input data-q="${i.id}" type="number" min="0" max="${remain}" step="any" value="${remain}"></label><label>Lot<input data-lot="${i.id}"></label><label>Expiry<input data-exp="${i.id}" type="date" value="${esc(inv?.expiry_date||'')}"></label></div></div>`}).join('')}</div>`,async()=>{const lines=r.items.map(i=>({procurement_item_id:i.id,qty:+document.querySelector(`[data-q="${i.id}"]`).value||0,lot_number:document.querySelector(`[data-lot="${i.id}"]`).value.trim(),expiry_date:document.querySelector(`[data-exp="${i.id}"]`).value||null})).filter(x=>x.qty>0);if(!lines.length)throw Error('Enter quantity to receive');await api.receiveRequest(id,lines);toast('Receipt recorded');await refresh()},'Receive')}
function usageModal(id){const x=db.inventory.find(i=>i.id===id),cs=db.containers.filter(c=>c.inventory_id===id&&c.status==='ACTIVE'&&Number(c.quantity_remaining)>0);modal(`Use ${x.name}`,`<div class="formgrid"><label>Quantity (${esc(x.unit)})<input id="u_qty" type="number" min="0.0001" step="any" value="1"></label><label>Container<select id="u_cont"><option value="">Automatic FEFO</option>${cs.map(c=>`<option value="${c.id}">${esc(c.container_code)} · ${c.quantity_remaining} · exp ${esc(c.expiry_date||'—')}</option>`).join('')}</select></label><label>Project<input id="u_proj" value="${esc(x.project||'')}"></label><label>Purpose<input id="u_purp"></label></div>`,async()=>{await api.consumeInventory(id,+$('#u_qty').value,$('#u_proj').value,$('#u_purp').value,$('#u_cont').value||null);toast('Usage recorded');await refresh()},'Record usage')}
function adjustModal(id){const x=db.inventory.find(i=>i.id===id);modal(`Adjust ${x.name}`,`<div class="formgrid"><label>New total stock<input id="a_stock" type="number" step="any" value="${x.current_stock}"></label><label>Reason<input id="a_reason" value="Stocktake correction"></label></div>`,async()=>{await api.adjustInventory(id,+$('#a_stock').value,$('#a_reason').value);toast('Stock adjusted');await refresh()})}
function invoiceModal(id){const r=db.procurement.find(x=>x.id===id);modal('Invoice reconciliation',`<div class="formgrid"><label>PO total<input value="${r.ordered_total||0}" disabled></label><label>Invoice amount<input id="i_amt" type="number" step="0.01" value="${r.invoice_amount??r.ordered_total??0}"></label><label>Invoice reference<input id="i_ref" value="${esc(r.invoice_ref||'')}"></label><label>Payment<select id="i_pay"><option>Unpaid</option><option>Paid</option><option>Partially Paid</option></select></label></div>`,async()=>{await api.updateInvoice(id,$('#i_amt').value,$('#i_ref').value,$('#i_pay').value);toast('Invoice updated');await refresh()})}
function containersModal(id){const x=db.inventory.find(i=>i.id===id),cs=db.containers.filter(c=>c.inventory_id===id);modal(`${x.name} containers`,`<div class="table-wrap"><table><thead><tr><th>Code</th><th>Lot</th><th>Remaining</th><th>Expiry</th><th>Status</th></tr></thead><tbody>${cs.map(c=>`<tr><td><b>${esc(c.container_code)}</b></td><td>${esc(c.lot_number||'—')}</td><td>${c.quantity_remaining} ${esc(c.unit)}</td><td>${esc(c.expiry_date||'—')}</td><td>${esc(c.status)}</td></tr>`).join('')}</tbody></table></div>`,async()=>{},'Close');$('#ms').onclick=()=>$('#modal').innerHTML=''}
async function documentsModal(type,id){try{const docs=await api.listAttachments(profile.lab_id,type,id);modal('Documents',`<div class="formgrid"><label class="full">Upload file<input id="d_file" type="file"></label></div><div style="margin-top:16px">${docs.map(d=>`<div class="auditrow"><button data-open="${d.id}">${esc(d.file_name)}</button><div class="sub">${new Date(d.created_at).toLocaleString()} · ${Math.round((d.size_bytes||0)/1024)} KB</div></div>`).join('')||'<div class="sub">No documents yet.</div>'}</div>`,async()=>{const f=$('#d_file').files[0];if(!f)throw Error('Choose a file');await api.uploadDocument(profile.lab_id,type,id,f);toast('Uploaded')},'Upload');$$('[data-open]').forEach(b=>b.onclick=async()=>{const d=docs.find(x=>x.id===+b.dataset.open);const r=await api.signedDocumentUrl(d.storage_path);window.open(r.signedUrl,'_blank')})}catch(e){fail(e)}}

function inviteUserModal(){modal('Invite lab user',`<div class="formgrid"><label>Email<input id="iu_email" type="email" required></label><label>Display name<input id="iu_name"></label><label>Role<select id="iu_role"><option value="member">Member</option><option value="admin">Admin</option></select></label><label>Invite redirect URL<input id="iu_redirect" value="${esc(location.origin+location.pathname)}"></label></div><div class="notice full">Requires the included Supabase Edge Function <code>invite-user</code> to be deployed.</div>`,async()=>{const email=$('#iu_email').value.trim();if(!email)throw Error('Email required');await api.inviteUser(email,$('#iu_name').value.trim(),$('#iu_role').value,$('#iu_redirect').value.trim());toast('Invitation sent')},'Send invite')}
function labModal(){modal('Laboratory settings',`<div class="formgrid"><label>Name<input id="l_name" value="${esc(db.lab.name||'')}"></label><label>PO prefix<input id="l_po" value="${esc(db.lab.po_prefix||'LABB-PO')}"></label><label class="full">Address<textarea id="l_addr">${esc(db.lab.address||'')}</textarea></label><label>Expiry notice days<input id="l_days" type="number" value="${db.lab.expiry_notice_days||90}"></label><label>Reorder horizon days<input id="l_reorder" type="number" value="${db.lab.reorder_horizon_days||30}"></label></div>`,async()=>{await api.updateLab(profile.lab_id,{name:$('#l_name').value.trim(),address:$('#l_addr').value.trim(),po_prefix:$('#l_po').value.trim(),expiry_notice_days:+$('#l_days').value||90,reorder_horizon_days:+$('#l_reorder').value||30});toast('Settings saved');await refresh()})}
function scanModal(){modal('Scan barcode / QR',`<div class="formgrid"><label class="full">Scan or type code<input id="s_code" autofocus placeholder="LABB-000001 / LABC-0000001 / SMP-... / EQ-..."></label><div class="full notice">USB/Bluetooth scanners can type directly into this field. Camera scanning uses the browser BarcodeDetector API when supported.</div></div>`,async()=>{const c=$('#s_code').value.trim();if(!c)throw Error('Enter or scan a code');resolveScannedCode(c)},'Find');const foot=$('#ms')?.parentElement;if(foot){const cam=document.createElement('button');cam.textContent='Use camera';cam.onclick=()=>cameraScan().catch(fail);foot.prepend(cam)}}
function printWindow(body){const w=window.open('','_blank');if(!w)return toast('Allow popups');w.document.write(`<html><head><style>body{font-family:Arial;padding:32px}.label{width:360px;border:2px solid #111;padding:18px}.code{font:700 24px monospace;letter-spacing:2px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #aaa;padding:8px}</style></head><body>${body}<script>setTimeout(()=>print(),250)<\/script></body></html>`);w.document.close()}
function printItem(id){const x=db.inventory.find(i=>i.id===id);printWindow(`<div class="label"><h2>${esc(x.name)}</h2><div class="code">${esc(x.item_code)}</div><p>${esc(x.sku||'')} · ${esc(x.storage||'')}</p><small>labb://inventory/${esc(x.item_code)}</small></div>`)}
function printPO(id){const r=db.procurement.find(x=>x.id===id),v=db.vendors.find(x=>x.id===r.vendor_id);printWindow(`<h1>${esc(db.lab.name)}</h1><p>${esc(db.lab.address||'')}</p><h2>${esc(r.po_number)}</h2><p>Vendor: ${esc(v?.name||'—')} · Project: ${esc(r.project||'')}</p><table><tr><th>Item</th><th>Qty</th><th>Unit</th></tr>${r.items.map(i=>{const inv=db.inventory.find(x=>x.id===i.inventory_id);return `<tr><td>${esc(inv?.name||'Item')}</td><td>${i.quantity}</td><td>${esc(i.unit)}</td></tr>`}).join('')}</table><h3>Total ${money(r.ordered_total)}</h3>`)}

if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
